function roundRobin(procs, quantum) {
  // procs: [{ id, arrival, burst }] sorted by arrival time
  const remaining = procs.map((p) => p.burst);
  const finish = new Array(procs.length).fill(0);
  const queue = []; // ready queue of process indices
  let time = 0, next = 0, done = 0;
  const admit = () => { // everyone who has arrived by "time" joins the queue
    while (next < procs.length && procs[next].arrival <= time) queue.push(next++);
  };
  admit();
  while (done < procs.length) {
    if (queue.length === 0) { time = procs[next].arrival; admit(); continue; } // idle CPU
    const i = queue.shift(); // dispatch the front of the queue
    const run = Math.min(quantum, remaining[i]);
    time += run;
    remaining[i] -= run;
    admit(); // arrivals during the slice queue up BEFORE the preempted process
    if (remaining[i] > 0) queue.push(i); // quantum expired: back of the queue
    else { finish[i] = time; done++; } // finished
  }
  const waiting = procs.map((p, i) => finish[i] - p.arrival - p.burst); // WT = TAT - BT
  const avg = procs.length ? waiting.reduce((a, b) => a + b, 0) / procs.length : 0;
  return { waiting, avg };
}

static double roundRobin(int[] arrival, int[] burst, int quantum, int[] waiting) {
    int n = arrival.length;                     // processes sorted by arrival
    int[] remaining = burst.clone();
    int[] finish = new int[n];
    Deque<Integer> queue = new ArrayDeque<>();
    int time = 0, next = 0, done = 0;
    while (next < n && arrival[next] <= time) queue.add(next++);
    while (done < n) {
        if (queue.isEmpty()) {                  // CPU idle until next arrival
            time = arrival[next];
            while (next < n && arrival[next] <= time) queue.add(next++);
            continue;
        }
        int i = queue.poll();
        int run = Math.min(quantum, remaining[i]);
        time += run;
        remaining[i] -= run;
        while (next < n && arrival[next] <= time) queue.add(next++); // arrivals first
        if (remaining[i] > 0) queue.add(i);
        else { finish[i] = time; done++; }
    }
    double total = 0;
    for (int i = 0; i < n; i++) {
        waiting[i] = finish[i] - arrival[i] - burst[i];
        total += waiting[i];
    }
    return n == 0 ? 0 : total / n;
}

function findSafeSequence(available, max, allocation) {
  const n = max.length, m = available.length;
  const need = max.map((row, i) => row.map((v, j) => v - allocation[i][j]));
  const work = [...available]; // resources free right now
  const finished = new Array(n).fill(false);
  const sequence = [];
  let progress = true;
  while (progress) {
    progress = false;
    for (let i = 0; i < n; i++) {
      if (finished[i]) continue;
      const canFinish = need[i].every((v, j) => v <= work[j]);
      if (canFinish) {
        for (let j = 0; j < m; j++) work[j] += allocation[i][j]; // i returns everything
        finished[i] = true;
        sequence.push('P' + i);
        progress = true;
      }
    }
  }
  return finished.every(Boolean) ? sequence : null; // null = unsafe state
}

static List<String> findSafeSequence(int[] available, int[][] max, int[][] allocation) {
    int n = max.length, m = available.length;
    int[] work = available.clone();            // resources free right now
    boolean[] finished = new boolean[n];
    List<String> sequence = new ArrayList<>();
    boolean progress = true;
    while (progress) {
        progress = false;
        for (int i = 0; i < n; i++) {
            if (finished[i]) continue;
            boolean canFinish = true;
            for (int j = 0; j < m; j++) {
                if (max[i][j] - allocation[i][j] > work[j]) { canFinish = false; break; }
            }
            if (canFinish) {
                for (int j = 0; j < m; j++) work[j] += allocation[i][j]; // release all
                finished[i] = true;
                sequence.add("P" + i);
                progress = true;
            }
        }
    }
    for (boolean f : finished) if (!f) return null;  // unsafe state
    return sequence;
}

import java.util.concurrent.Semaphore;
import java.util.concurrent.locks.ReentrantLock;

class Resources {
    private final ReentrantLock lock = new ReentrantLock(); // mutex: one owner
    private final Semaphore dbSlots = new Semaphore(2);     // 2 permits
    private int counter = 0;

    void increment() {
        lock.lock();
        try {
            counter++;                 // critical section
        } finally {
            lock.unlock();             // only the owning thread may unlock
        }
    }

    void queryDatabase(String who) throws InterruptedException {
        dbSlots.acquire();             // wait / P: take a permit or block
        try {
            System.out.println(who + " is using a connection");
        } finally {
            dbSlots.release();         // signal / V: return the permit
        }
    }

    int count() { return counter; }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.concurrent.Semaphore;
import java.util.concurrent.locks.ReentrantLock;

class BoundedBuffer {
    private final Queue<Integer> items = new ArrayDeque<>();
    private final Semaphore empty;                    // free slots
    private final Semaphore full = new Semaphore(0);  // filled slots
    private final ReentrantLock mutex = new ReentrantLock(); // guards "items"

    BoundedBuffer(int capacity) { empty = new Semaphore(capacity); }

    void produce(int item) throws InterruptedException {
        empty.acquire();                 // wait for a free slot
        mutex.lock();
        try { items.add(item); } finally { mutex.unlock(); }
        full.release();                  // one more item to consume
    }

    int consume() throws InterruptedException {
        full.acquire();                  // wait for an item
        int item;
        mutex.lock();
        try { item = items.remove(); } finally { mutex.unlock(); }
        empty.release();                 // one more free slot
        return item;
    }
}

const PAGE_SIZE = 4096; // 4 KB pages -> the low 12 bits are the offset

function translate(va, tlb, pageTable, loadPage) {
  const page = Math.floor(va / PAGE_SIZE); // high bits: virtual page number
  const offset = va % PAGE_SIZE;           // low bits: copied unchanged
  let frame = tlb.get(page);               // 1) TLB: tiny, very fast cache
  if (frame === undefined) {               // TLB miss
    const entry = pageTable[page];         // 2) walk the page table in RAM
    if (!entry.valid) {                    // 3) page fault: OS brings page in
      entry.frame = loadPage(page);
      entry.valid = true;
    }
    frame = entry.frame;
    tlb.set(page, frame);                  // cache the translation
  }
  return frame * PAGE_SIZE + offset;       // physical address
}

static final int PAGE_SIZE = 4096;  // 4 KB pages -> 12 offset bits

static int translate(int va, Map<Integer, Integer> tlb, int[] frameOf,
                     boolean[] valid, IntUnaryOperator loadPage) {
    int page = va / PAGE_SIZE;         // virtual page number
    int offset = va % PAGE_SIZE;       // copied unchanged
    Integer frame = tlb.get(page);     // 1) TLB lookup
    if (frame == null) {               // TLB miss
        if (!valid[page]) {            // 2) page table says "not in RAM"
            frameOf[page] = loadPage.applyAsInt(page);  // 3) page fault
            valid[page] = true;
        }
        frame = frameOf[page];
        tlb.put(page, frame);          // cache the translation
    }
    return frame * PAGE_SIZE + offset;
}

function lruPageFaults(refs, capacity) {
  const frames = new Set(); // Set keeps insertion order: oldest use first
  let faults = 0;
  for (const page of refs) {
    if (frames.has(page)) {
      frames.delete(page); // hit: re-insert below as most recently used
    } else {
      faults++; // page fault
      if (frames.size === capacity) {
        const lru = frames.values().next().value; // least recently used
        frames.delete(lru); // evict it
      }
    }
    frames.add(page); // page is now the most recently used
  }
  return faults;
}

from collections import OrderedDict

def lru_page_faults(refs, capacity):
    frames = OrderedDict()             # oldest use first
    faults = 0
    for page in refs:
        if page in frames:
            frames.move_to_end(page)   # hit: now most recently used
            continue
        faults += 1                    # page fault
        if len(frames) == capacity:
            frames.popitem(last=False) # evict the least recently used
        frames[page] = True
    return faults

static int lruPageFaults(int[] refs, int capacity) {
    LinkedHashSet<Integer> frames = new LinkedHashSet<>(); // oldest use first
    int faults = 0;
    for (int page : refs) {
        if (frames.contains(page)) {
            frames.remove(page);              // hit: re-insert as most recent
        } else {
            faults++;                         // page fault
            if (frames.size() == capacity) {
                int lru = frames.iterator().next();  // least recently used
                frames.remove(lru);
            }
        }
        frames.add(page);
    }
    return faults;
}

