const { Worker, isMainThread, parentPort, workerData } = require('node:worker_threads');

const sleep = (ms, label) => new Promise((resolve) => setTimeout(() => resolve(label), ms));

// Concurrency: ONE thread keeps three waits (think DB / API / cache calls) in flight
async function concurrency() {
  const t0 = Date.now();
  const res = await Promise.all([sleep(300, 'db'), sleep(300, 'api'), sleep(300, 'cache')]);
  console.log(res.join(','), Date.now() - t0 < 600 ? '~300ms, not 900ms' : 'slow');
}

// Parallelism: split CPU work across worker threads = several cores at once
function sumRange(from, to) {
  let s = 0;
  for (let i = from; i < to; i++) s += i;
  return s;
}

function parallelSum(n, workers) {
  const chunk = Math.ceil(n / workers);
  const jobs = [];
  for (let w = 0; w < workers; w++) {
    const from = w * chunk, to = Math.min(n, from + chunk);
    jobs.push(new Promise((resolve, reject) => {
      const worker = new Worker(__filename, { workerData: { from, to } });
      worker.on('message', resolve);
      worker.on('error', reject);
    }));
  }
  return Promise.all(jobs).then((parts) => parts.reduce((a, b) => a + b, 0));
}

if (isMainThread) {
  concurrency().then(() => parallelSum(10_000_000, 4)).then((s) => console.log('sum =', s));
} else {
  parentPort.postMessage(sumRange(workerData.from, workerData.to));
}
